    private void createShelf(){final EditText input=new EditText(this);input.setHint("书架名称");Ui.styleField(input,this);new AlertDialog.Builder(this).setTitle("新建书架").setView(input).setNegativeButton("取消",null).setPositiveButton("创建",(d,w)->{try{ShelfStore.Shelf shelf=ShelfStore.create(this,input.getText().toString());activeShelfId=shelf.id;prefs.edit().putString("activeShelfId",activeShelfId).apply();syncShelves();show();}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}}).show();}
