    private void recommendations(){LinearLayout p=page(true);RecommendationProgressPanel progress=new RecommendationProgressPanel(this,()->{if(current==1&&!isDestroyed()&&!isFinishing())show();});titleRow(p,"为你推荐",Ui.iconButton(this,R.drawable.ic_refresh_24,"刷新推荐",v->{NativeRecommendationJobs.refresh(this);progress.begin();}));p.addView(progress);if(!PicaAccountStore.load(this).configured()){TextView t=Ui.text(this,"登录 Pica 后即可根据收藏生成推荐。",14,Ui.MUTED,false);t.setPadding(0,Ui.dp(this,20),0,Ui.dp(this,10));p.addView(t);p.addView(compact("登录 Pica",v->startActivity(new Intent(this,PicaAccountActivity.class))));return;}NativeRecommendationStore.Snapshot snapshot=NativeRecommendationStore.load(this);if(!snapshot.available()){TextView t=Ui.text(this,"还没有推荐结果",14,Ui.MUTED,false);t.setPadding(0,Ui.dp(this,20),0,Ui.dp(this,10));p.addView(t);p.addView(compact("生成推荐",v->{NativeRecommendationJobs.refresh(this);progress.begin();}));return;}LinearLayout pager=new LinearLayout(this);pager.setGravity(Gravity.CENTER_VERTICAL);pager.addView(compact("上一批",v->{NativeRecommendationStore.previousBatch(this);show();}),new LinearLayout.LayoutParams(0,-2,1));TextView batch=Ui.text(this,"第 "+(snapshot.batchIndex+1)+" / "+snapshot.batches.size()+" 批",13,Ui.MUTED,false);batch.setGravity(Gravity.CENTER);pager.addView(batch,new LinearLayout.LayoutParams(0,-1,1));pager.addView(compact("下一批",v->{NativeRecommendationStore.nextBatch(this);show();}),new LinearLayout.LayoutParams(0,-2,1));p.addView(pager);UnifiedCatalogStore.Snapshot catalog=UnifiedCatalogStore.load(this);for(NativeRecommendationStore.Item item:snapshot.current()){UnifiedCatalogStore.Entry e=catalog.byId.get(item.comicId);if(e==null)e=new UnifiedCatalogStore.Entry(item.comicId,item.title,item.author);LinearLayout card=Ui.card(this);card.setOrientation(LinearLayout.HORIZONTAL);ImageView cover=new ImageView(this);cover.setScaleType(ImageView.ScaleType.CENTER_CROP);cover.setBackgroundColor(Ui.PLACEHOLDER);card.addView(cover,new LinearLayout.LayoutParams(Ui.dp(this,86),Ui.dp(this,122)));LinearLayout copy=new LinearLayout(this);copy.setOrientation(LinearLayout.VERTICAL);copy.setPadding(Ui.dp(this,12),0,0,0);copy.addView(Ui.text(this,item.title,16,Ui.TEXT,true));copy.addView(Ui.text(this,item.author,12,Ui.MUTED,false));TextView why=Ui.text(this,item.reason,12,Ui.PRIMARY,false);why.setPadding(0,Ui.dp(this,6),0,0);copy.addView(why);card.addView(copy,new LinearLayout.LayoutParams(0,-2,1));UnifiedCatalogStore.Entry target=e;card.setOnClickListener(v->open(target));CoverRepository.load(this,cover,e,Ui.PLACEHOLDER);p.addView(card);}NativeRecommendationStore.markCurrentSeen(this);}

    private void online(){LinearLayout p=page(false);titleRow(p,"在线",Ui.iconButton(this,R.drawable.ic_person_24,"Pica 账号",v->startActivity(new Intent(this,PicaAccountActivity.class))));if(!PicaAccountStore.load(this).configured()){TextView t=Ui.text(this,"登录 Pica 后可搜索、浏览、收藏和在线阅读。",14,Ui.MUTED,false);t.setPadding(0,Ui.dp(this,36),0,Ui.dp(this,12));p.addView(t);p.addView(compact("登录 Pica",v->startActivity(new Intent(this,PicaAccountActivity.class))));return;}EditText search=new EditText(this);search.setSingleLine(true);search.setHint("搜索 Pica 漫画");search.setText("search".equals(onlineMode)?onlineKeyword:"");search.setImeOptions(EditorInfo.IME_ACTION_SEARCH);Ui.styleField(search,this);search.setOnEditorActionListener((v,id,event)->{if(id==EditorInfo.IME_ACTION_SEARCH){onlineKeyword=v.getText().toString().trim();onlineMode="search";onlinePage=1;resetTabScroll(2);show();return true;}return false;});p.addView(search);LinearLayout actions=new LinearLayout(this);actions.setPadding(0,Ui.dp(this,7),0,Ui.dp(this,3));actions.addView(compact("收藏",v->{onlineMode="favorites";onlinePage=1;resetTabScroll(2);show();}),new LinearLayout.LayoutParams(0,-2,1));Ui.gap(actions,this,6);actions.addView(compact("排行",v->chooseLeaderboardRange()),new LinearLayout.LayoutParams(0,-2,1));Ui.gap(actions,this,6);actions.addView(compact("分类",v->chooseOnlineCategory()),new LinearLayout.LayoutParams(0,-2,1));p.addView(actions);TextView status=Ui.text(this,"正在读取…",12,Ui.MUTED,false);status.setPadding(0,Ui.dp(this,4),0,0);p.addView(status);RecyclerView list=collection(p,UnifiedComicCollectionAdapter.MODE_LIST);loadOnline(list,status);}
    private void loadOnline(RecyclerView list,TextView status){final int id=serial;pending=worker.submit(()->{try{PicaClient client=new PicaClient(this);List<PicaClient.Comic> comics;int pages=1,currentPage=onlinePage;if("favorites".equals(onlineMode)){PicaClient.ComicPage value=client.favorites(onlinePage,"dd");comics=value.comics;pages=value.pages;currentPage=value.page;}else if("search".equals(onlineMode)){PicaClient.ComicPage value=client.search(onlineKeyword,onlinePage,"ld",Collections.emptyList());comics=value.comics;pages=value.pages;currentPage=value.page;}else if("category".equals(onlineMode)){PicaClient.ComicPage value=client.browse(onlineCategory,"","dd",onlinePage);comics=value.comics;pages=value.pages;currentPage=value.page;}else{comics=client.leaderboard(leaderboardRange);onlinePage=1;}UnifiedPicaCatalogSync.mergeAll(this,comics);if("favorites".equals(onlineMode)){UnifiedCatalogStore.Snapshot s=UnifiedCatalogStore.load(this);for(PicaClient.Comic c:comics){UnifiedCatalogStore.Entry e=s.byId.get(c.id);if(e!=null)e.favorite=true;}UnifiedCatalogStore.save(this,s);}UnifiedCatalogStore.Snapshot catalog=UnifiedCatalogStore.load(this);List<UnifiedCatalogStore.Entry> entries=new ArrayList<>();for(PicaClient.Comic c:comics){UnifiedCatalogStore.Entry e=catalog.byId.get(c.id);if(e!=null)entries.add(e);}final int pageCount=pages,shownPage=currentPage;runOnUiThread(()->{if(id!=serial||isDestroyed())return;status.setText(onlineLabel()+("leaderboard".equals(onlineMode)?" · "+entries.size()+" 本":" · 第 "+shownPage+" / "+pageCount+" 页"));list.setAdapter(new UnifiedComicCollectionAdapter(this,UnifiedComicCollectionAdapter.MODE_LIST,entries,this::open));restoreListPosition(list,2);if(pageCount>1){LinearLayout navRow=new LinearLayout(this);navRow.setPadding(0,Ui.dp(this,5),0,0);navRow.addView(compact("上一页",v->{if(onlinePage>1){onlinePage--;resetTabScroll(2);show();}}),new LinearLayout.LayoutParams(0,-2,1));Ui.gap(navRow,this,8);navRow.addView(compact("下一页",v->{if(onlinePage<pageCount){onlinePage++;resetTabScroll(2);show();}}),new LinearLayout.LayoutParams(0,-2,1));((LinearLayout)list.getParent()).addView(navRow);}});}catch(Exception e){runOnUiThread(()->{if(id==serial)status.setText("读取失败："+(e.getMessage()==null?"请稍后重试":e.getMessage()));});}});}
    private String onlineLabel(){if("favorites".equals(onlineMode))return "我的收藏";if("search".equals(onlineMode))return onlineKeyword;if("category".equals(onlineMode))return onlineCategory;return "排行 · "+leaderboardRangeLabel();}
    private String leaderboardRangeLabel(){if("D7".equals(leaderboardRange))return "7 天";if("D30".equals(leaderboardRange))return "30 天";return "24 小时";}
    private void chooseLeaderboardRange(){String[] labels={"24 小时","7 天","30 天"};String[] values={"H24","D7","D30"};int checked="D7".equals(leaderboardRange)?1:"D30".equals(leaderboardRange)?2:0;new AlertDialog.Builder(this).setTitle("排行榜范围").setSingleChoiceItems(labels,checked,(d,which)->{leaderboardRange=values[which];onlineMode="leaderboard";onlinePage=1;resetTabScroll(2);d.dismiss();show();}).setNegativeButton("取消",null).show();}
    private void chooseOnlineCategory(){worker.submit(()->{try{List<String> values=new PicaClient(this).categories();runOnUiThread(()->new AlertDialog.Builder(this).setTitle("分类").setItems(values.toArray(new String[0]),(d,i)->{onlineCategory=values.get(i);onlineMode="category";onlinePage=1;resetTabScroll(2);show();}).show());}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"分类读取失败",Toast.LENGTH_SHORT).show());}});}

    private interface Probe {String check() throws Exception;}
    private void connections(){LinearLayout p=page(true);titleRow(p,"连接与设置");boolean desktop=BridgeStore.paired(this),webdav=RemoteConfigStore.load(this).configured(),pica=PicaAccountStore.load(this).configured();connectionCard(p,"局域网电脑",desktop,desktop?"已配对":"未配对",desktop?"管理连接":"配对电脑",v->startActivity(new Intent(this,PairingActivity.class)),desktop,()->{BridgeClient.device(this);return "在线 · "+BridgeStore.serverName(this);});connectionCard(p,"WebDAV",webdav,webdav?"已配置":"未配置","管理 WebDAV",v->startActivity(new Intent(this,RemoteStorageActivity.class)),webdav,()->new RemoteLibraryClient(this).test()?"可连接":"连接异常");connectionCard(p,"Pica",pica,pica?"已配置":"未配置","账号",v->startActivity(new Intent(this,PicaAccountActivity.class)),pica,()->{new PicaClient(this).categories();return "可用";});
        LinearLayout appearance=Ui.card(this);LinearLayout ah=new LinearLayout(this);ah.setGravity(Gravity.CENTER_VERTICAL);ah.addView(Ui.text(this,"外观",18,Ui.TEXT,true),new LinearLayout.LayoutParams(0,-2,1));ah.addView(Ui.pill(this,ThemeStore.label(this),Ui.PRIMARY_SOFT,Ui.PRIMARY));appearance.addView(ah);appearance.addView(compact("外观设置",v->startActivity(new Intent(this,AppearanceActivity.class))));p.addView(appearance);
        LinearLayout storage=Ui.card(this);storage.addView(Ui.text(this,"存储与下载",18,Ui.TEXT,true));LinearLayout row=new LinearLayout(this);row.setPadding(0,Ui.dp(this,8),0,0);row.addView(compact("存储与缓存",v->startActivity(new Intent(this,StorageSettingsActivity.class))),new LinearLayout.LayoutParams(0,-2,1));Ui.gap(row,this,8);row.addView(compact("下载任务",v->startActivity(new Intent(this,DownloadsActivity.class))),new LinearLayout.LayoutParams(0,-2,1));storage.addView(row);p.addView(storage);
        LinearLayout update=Ui.card(this);update.addView(Ui.text(this,"软件更新",18,Ui.TEXT,true));Button check=compact("检查更新",v->startActivity(new Intent(this,UpdateActivity.class)));LinearLayout.LayoutParams up=new LinearLayout.LayoutParams(-1,-2);up.setMargins(0,Ui.dp(this,8),0,0);update.addView(check,up);p.addView(update);
        LinearLayout about=Ui.card(this);about.addView(Ui.text(this,"支持项目",18,Ui.TEXT,true));TextView thanks=Ui.text(this,"感谢你使用 Pica Library。",13,Ui.MUTED,false);thanks.setPadding(0,Ui.dp(this,8),0,Ui.dp(this,10));about.addView(thanks);LinearLayout support=new LinearLayout(this);support.addView(compact("⭐ GitHub 项目主页",v->openUrl(REPO_URL)),new LinearLayout.LayoutParams(-1,-2));about.addView(support);p.addView(about);
        if(desktop)worker.submit(()->{try{BridgeClient.device(this);ShelfStore.syncWithDesktop(this);SupporterSyncJobs.enqueue(this);}catch(Exception ignored){}});
    }
    private void connectionCard(LinearLayout p,String title,boolean configured,String configuredLabel,String action,View.OnClickListener click,boolean probeEnabled,Probe probe){LinearLayout card=Ui.card(this);LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);head.addView(Ui.text(this,title,18,Ui.TEXT,true),new LinearLayout.LayoutParams(0,-2,1));head.addView(Ui.pill(this,configuredLabel,configured?Ui.GOOD_SOFT:Ui.ACTION,configured?Ui.GOOD:Ui.MUTED));card.addView(head);LinearLayout currentRow=new LinearLayout(this);currentRow.setGravity(Gravity.CENTER_VERTICAL);currentRow.setPadding(0,Ui.dp(this,9),0,Ui.dp(this,8));currentRow.addView(Ui.text(this,"当前状态",12.5f,Ui.MUTED,false),new LinearLayout.LayoutParams(0,-2,1));TextView currentPill=Ui.pill(this,configured?"检查中":"未连接",configured?Ui.WARN_SOFT:Ui.ACTION,configured?Ui.WARN:Ui.MUTED);currentRow.addView(currentPill);card.addView(currentRow);card.addView(compact(action,click));p.addView(card);if(probeEnabled){final int id=serial;worker.submit(()->{try{String value=probe.check();runOnUiThread(()->{if(id==serial&&!isDestroyed())Ui.stylePill(currentPill,this,value,Ui.GOOD_SOFT,Ui.GOOD);});}catch(Exception e){runOnUiThread(()->{if(id==serial&&!isDestroyed())Ui.stylePill(currentPill,this,"当前不可用",Ui.WARN_SOFT,Ui.WARN);});}});}}
    private void openUrl(String url){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){Toast.makeText(this,"无法打开浏览器",Toast.LENGTH_SHORT).show();}}
